import { isImeComposing } from "@/lib/ime";
import {
  type ButtonHTMLAttributes,
  forwardRef,
  type ReactElement,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
  useState,
} from "react";
import { Popover as BasePopover } from "@base-ui/react/popover";

import { cn } from "@/lib/cn";
import { useGlide } from "@/lib/glide";
import { Check, ChevronDown } from "lucide-react";
import { useOverlayRoot, useOverlayDismiss } from "@/components/ui/overlay-root";
import { Input } from "./input.js";
import { useSelectableCollection } from "./selectable.js";

/** The same molded field face as Select, for caller-owned selection summaries. */
export const ComboboxTrigger = forwardRef<
  HTMLButtonElement,
  ButtonHTMLAttributes<HTMLButtonElement>
>(function ComboboxTrigger(
  { children, className, type = "button", ...props },
  ref,
) {
  return (
    <button
      {...props}
      ref={ref}
      type={type}
      className={cn(
        "select caps-select caps-combobox-trigger w-full",
        className,
      )}
    >
      <span>{children}</span>
      <ChevronDown className="caps-select-chevron" aria-hidden="true" />
    </button>
  );
});

/** Intrinsic focus and selection state supplied when rendering a Combobox item. */
export type ComboboxItemState = {
  active: boolean;
  disabled: boolean;
  selected: boolean;
};
/** Props accepted by Combobox. */
export type ComboboxProps<T> = ComboboxBaseProps<T> &
  (ComboboxInlineProps | ComboboxPopupProps) &
  ComboboxValueProps<T>;
/** Props shared by every Combobox mode: item shape, rendering, and field wiring. */
export type ComboboxBaseProps<T> = {
  /** Color intent for the locally active option. */
  activeTone?: "neutral" | "primary";
  /** Native portal destination. Use an unclipped themed container for nested themes. */
  container?: BasePopover.Portal.Props["container"];
  contentClassName?: string;
  emptyMessage?: ReactNode;
  /** Returns the stable identity used to track and compare items. */
  getKey: (item: T) => string;
  /** Returns the text shown for an item in the trigger and the list. */
  getLabel: (item: T) => string;
  /** Returns the text matched against caller input; defaults to the item's label. */
  getSearchText?: (item: T) => string;
  /** Returns the heading an item is grouped under in the list. */
  groupBy?: (item: T) => string;
  /** Identifies the popup trigger or inline input for native label association. */
  id?: string;
  inputProps?: Omit<
    React.InputHTMLAttributes<HTMLInputElement>,
    "defaultValue" | "value"
  >;
  inputRef?: React.Ref<HTMLInputElement>;
  /** Receives the selection control's root div. */
  rootRef?: React.Ref<HTMLDivElement>;
  /** Returns whether an item is unselectable. */
  isDisabled?: (item: T) => boolean;
  items: readonly T[];
  placeholder?: string;
  /** Renders one item's content; defaults to its label. */
  renderItem?: (
    item: T,
    active: boolean,
    state: ComboboxItemState,
  ) => ReactNode;
} & Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue" | "value">;

/** Combobox mode flags for the inline (always-expanded, no popup trigger) layout. */
export type ComboboxInlineProps = {
  defaultOpen?: never;
  /** Popup visibility callbacks do not apply to inline choices. */
  onOpenChange?: never;
  open?: never;
  trigger?: never;
  triggerRef?: never;
};

/** Combobox mode flags for the popup layout, either caller-controlled or uncontrolled open state. */
export type ComboboxPopupProps =
  | {
      defaultOpen?: boolean;
      /** Called after the popup's open state changes. */
      onOpenChange?: (open: boolean) => void;
      open?: never;
      trigger: ReactElement<ButtonHTMLAttributes<HTMLButtonElement>>;
      triggerRef?: React.Ref<HTMLButtonElement>;
    }
  | {
      defaultOpen?: never;
      /** Called after the popup's open state changes. */
      onOpenChange?: (open: boolean) => void;
      open: boolean;
      trigger: ReactElement<ButtonHTMLAttributes<HTMLButtonElement>>;
      triggerRef?: React.Ref<HTMLButtonElement>;
    };

/** Combobox selection shape: single or multiple, controlled or uncontrolled. */
export type ComboboxValueProps<T> =
  | ((
      | {
          defaultValue?: never;
          value: null | string;
        }
      | {
          defaultValue?: null | string;
          value?: never;
        }
    ) & {
      multiple?: false;
      /** Called with the newly selected key and item, or null when cleared. */
      onValueChange?: (value: null | string, item: null | T) => void;
    })
  | {
      multiple: true;
      value: readonly string[];
      defaultValue?: never;
      /** Called with the newly selected keys and items. */
      onValueChange?: (value: string[], items: T[]) => void;
    };

type ComboboxControllerOptions<T> = {
  defaultOpen: boolean;
  defaultValue: null | string;
  /** Stable identity used to track an item across renders. */
  getKey: (item: T) => string;
  getSearchText: (item: T) => string;
  groupBy: ((item: T) => string) | undefined;
  id: string;
  isDisabled: (item: T) => boolean;
  items: readonly T[];
  onOpenChange: ((open: boolean) => void) | undefined;
  onCommit: (item: T) => void;
  multiple: boolean;
  controlledOpen: boolean | undefined;
  controlledKeys: readonly string[] | undefined;
  trigger: ReactElement | undefined;
};

type ComboboxGroup<T> = {
  label: string;
  items: readonly T[];
};

function useComboboxController<T>({
  defaultOpen,
  defaultValue,
  getKey,
  getSearchText,
  groupBy,
  id,
  isDisabled,
  items,
  onOpenChange,
  onCommit,
  multiple,
  controlledOpen,
  controlledKeys,
  trigger,
}: ComboboxControllerOptions<T>) {
  const listboxId = `${id}-listbox`;
  const [query, setQuery] = useState("");
  const [keyboardNavigation, setKeyboardNavigation] = useState(false);
  const [uncontrolledValue, setUncontrolledValue] = useState<null | string>(
    defaultValue,
  );
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const selectedKeys =
    controlledKeys ?? (uncontrolledValue === null ? [] : [uncontrolledValue]);
  const open = trigger ? (controlledOpen ?? uncontrolledOpen) : true;
  const filtered = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    return normalizedQuery
      ? items.filter((item) =>
          getSearchText(item).toLowerCase().includes(normalizedQuery),
        )
      : items;
  }, [getSearchText, items, query]);
  const collection = useSelectableCollection({
    getKey,
    isDisabled,
    items: filtered,
  });

  useEffect(() => {
    if (collection.activeKey !== null) return;
    const initial =
      collection.enabledItems.find((item) =>
        selectedKeys.includes(getKey(item)),
      ) ?? collection.enabledItems[0];
    if (initial) collection.setActiveKey(getKey(initial));
  }, [
    collection.activeKey,
    collection.enabledItems,
    collection.setActiveKey,
    getKey,
    selectedKeys,
  ]);

  const setOpen = (next: boolean) => {
    setKeyboardNavigation(false);
    if (!next) setQuery("");
    if (controlledOpen === undefined) setUncontrolledOpen(next);
    onOpenChange?.(next);
  };
  const optionId = (key: string) =>
    `${listboxId}-option-${encodeURIComponent(key)}`;
  const commit = (item: T) => {
    const next = getKey(item);
    if (controlledKeys === undefined) setUncontrolledValue(next);
    onCommit(item);
    if (trigger && !multiple) setOpen(false);
  };
  const onInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setKeyboardNavigation(true);
    setQuery(event.target.value);
    collection.setActiveKey(null);
  };
  const onInputKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (isImeComposing(event)) return;
    let move: readonly [-1 | 1, "end" | "start" | undefined] | undefined;
    switch (event.key) {
      case "ArrowDown":
        move = [1, undefined];
        break;
      case "ArrowUp":
        move = [-1, undefined];
        break;
      case "End":
        move = [1, "end"];
        break;
      case "Home":
        move = [-1, "start"];
        break;
    }
    if (move) {
      setKeyboardNavigation(true);
      event.preventDefault();
      collection.move(move[0], move[1]);
    } else if (event.key === "Enter" && collection.activeItem) {
      event.preventDefault();
      commit(collection.activeItem);
    }
  };
  const groups = useMemo<readonly ComboboxGroup<T>[]>(() => {
    if (!groupBy) return [{ label: "", items: filtered }];
    const grouped = new Map<string, T[]>();
    for (const item of filtered) {
      const label = groupBy(item);
      const group = grouped.get(label);
      if (group) group.push(item);
      else grouped.set(label, [item]);
    }
    return [...grouped].map(([label, groupItems]) => ({
      label,
      items: groupItems,
    }));
  }, [filtered, groupBy]);

  return {
    keyboardNavigation,
    onPointerMove: () => {
      setKeyboardNavigation(false);
    },
    activeKey: collection.activeKey,
    activeItem: collection.activeItem,
    groups,
    inputValue: query,
    listboxId,
    onInputChange,
    onInputKeyDown,
    optionId,
    open,
    commit,
    selectedKeys,
    setOpen,
  };
}

/** A searchable selection primitive with caller-owned values and intrinsic keyboard navigation. */
export function Combobox<T>(props: ComboboxProps<T>) {
  const {
    "aria-describedby": describedBy,
    "aria-invalid": invalid,
    "aria-label": label,
    "aria-labelledby": labelledBy,
    "aria-required": required,
    activeTone = "neutral",
    container,
    contentClassName,
    defaultOpen = false,
    defaultValue = null,
    emptyMessage = "No matches",
    getKey,
    getLabel,
    getSearchText = getLabel,
    groupBy,
    id: providedId,
    inputProps,
    inputRef,
    isDisabled = () => false,
    items,
    onOpenChange,
    onValueChange,
    multiple,
    open: controlledOpen,
    placeholder = "Search…",
    renderItem,
    rootRef,
    trigger,
    triggerRef,
    value: controlledValue,
    ...rootProps
  } = props;
  // Keep the public single/multiple callback types correlated at this boundary.
  const onCommit = (item: T) => {
    const key = getKey(item);
    if (multiple) {
      const next = controlledValue.includes(key)
        ? controlledValue.filter((value) => value !== key)
        : [...controlledValue, key];
      onValueChange?.(
        next,
        items.filter((entry) => next.includes(getKey(entry))),
      );
    } else {
      onValueChange?.(key, item);
    }
  };
  let controlledKeys: readonly string[] | undefined;
  if (multiple) controlledKeys = controlledValue;
  else if (controlledValue !== undefined)
    controlledKeys = controlledValue === null ? [] : [controlledValue];
  const generatedId = useId();
  const controlProps = trigger?.props ?? inputProps;
  const id = providedId ?? controlProps?.id ?? generatedId;
  const selectionControlProps = {
    id,
    "aria-describedby":
      [describedBy, controlProps?.["aria-describedby"]]
        .filter(Boolean)
        .join(" ") || undefined,
    "aria-invalid": invalid ?? controlProps?.["aria-invalid"],
    "aria-label": controlProps?.["aria-label"] ?? label,
    "aria-labelledby": controlProps?.["aria-labelledby"] ?? labelledBy,
    "aria-required": required ?? controlProps?.["aria-required"],
  };
  const controller = useComboboxController({
    defaultOpen,
    defaultValue,
    getKey,
    getSearchText,
    groupBy,
    id,
    isDisabled,
    items,
    onOpenChange,
    onCommit,
    multiple: multiple ?? false,
    controlledOpen,
    controlledKeys,
    trigger,
  });
  const {
    keyboardNavigation,
    onPointerMove,
    activeItem,
    activeKey,
    commit,
    groups,
    inputValue,
    listboxId,
    onInputChange,
    onInputKeyDown,
    open,
    optionId,
    selectedKeys,
    setOpen,
  } = controller;
  useOverlayDismiss(() => {
    if (trigger) setOpen(false);
  });
  const overlay = useOverlayRoot("popover");
  const portalContainer = container === undefined ? overlay : container;
  const listRef = useGlide(
    '.caps-combobox-option[data-active="true"]:not(:disabled), [data-navigation="pointer"] .caps-combobox-option:hover:not(:disabled)',
  );
  const input = (
    <Input
      {...inputProps}
      {...(trigger ? {} : selectionControlProps)}
      aria-activedescendant={
        activeItem ? optionId(getKey(activeItem)) : undefined
      }
      aria-autocomplete="list"
      aria-controls={listboxId}
      aria-expanded={true}
      className={cn("input-sm", inputProps?.className)}
      id={trigger ? (inputProps?.id ?? `${id}-input`) : id}
      onChange={(event) => {
        inputProps?.onChange?.(event);
        onInputChange(event);
      }}
      onKeyDown={(event) => {
        inputProps?.onKeyDown?.(event);
        if (!event.defaultPrevented) onInputKeyDown(event);
      }}
      placeholder={inputProps?.placeholder ?? placeholder}
      ref={inputRef}
      role="combobox"
      value={inputValue}
    />
  );
  const list = (
    <div
      id={listboxId}
      ref={listRef}
      className="caps-combobox-list"
      data-navigation={keyboardNavigation ? "keyboard" : "pointer"}
      onPointerMove={onPointerMove}
      role="listbox"
      aria-multiselectable={multiple ?? undefined}
    >
      {groups.every((group) => group.items.length === 0) ? (
        <div className="px-md py-md text-sm text-base-content">
          {emptyMessage}
        </div>
      ) : (
        groups.map((group) => (
          <div
            aria-label={group.label || undefined}
            key={group.label}
            role={group.label ? "group" : undefined}
          >
            {group.label ? (
              <div className="px-md pb-xs pt-sm text-xs text-base-content uppercase tracking-wider">
                {group.label}
              </div>
            ) : null}
            {group.items.map((item) => {
              const key = getKey(item);
              const disabled = isDisabled(item);
              const active = activeKey === key;
              const state = {
                active,
                disabled,
                selected: selectedKeys.includes(key),
              };
              return (
                <button
                  aria-disabled={disabled || undefined}
                  aria-selected={state.selected}
                  className="caps-combobox-option"
                  data-active={active && keyboardNavigation}
                  disabled={disabled}
                  id={optionId(key)}
                  key={key}
                  onClick={() => {
                    commit(item);
                  }}
                  onMouseDown={(event) => {
                    // Keep typing in the search field after a pointer selection.
                    event.preventDefault();
                  }}
                  role="option"
                  tabIndex={-1}
                  type="button"
                >
                  <span aria-hidden="true" className="caps-combobox-check">
                    {state.selected ? <Check /> : null}
                  </span>
                  {renderItem?.(item, active, state) ?? getLabel(item)}
                </button>
              );
            })}
          </div>
        ))
      )}
    </div>
  );
  if (!trigger)
    return (
      <div {...rootProps} className={cn(rootProps.className)} ref={rootRef}>
        <div
          className={cn("caps-combobox-panel", contentClassName)}
          data-active-tone={activeTone}
        >
          <div className="caps-combobox-search">{input}</div>
          {list}
        </div>
      </div>
    );
  return (
    <div {...rootProps} className={cn(rootProps.className)} ref={rootRef}>
      <BasePopover.Root modal onOpenChange={setOpen} open={open}>
        <BasePopover.Trigger
          {...selectionControlProps}
          aria-haspopup="dialog"
          className="btn"
          ref={triggerRef}
          render={trigger}
        />
        {portalContainer !== null ? (
          <BasePopover.Portal container={portalContainer}>
            <BasePopover.Positioner align="start" side="bottom" sideOffset={4}>
              <BasePopover.Popup
                data-active-tone={activeTone}
                className={cn(
                  "min-w-40 rounded-box border border-base-300 bg-base-100 p-xs shadow-lg outline-none caps-combobox-panel caps-combobox-popup",
                  contentClassName,
                )}
              >
                <div className="caps-combobox-search">{input}</div>
                {list}
              </BasePopover.Popup>
            </BasePopover.Positioner>
          </BasePopover.Portal>
        ) : null}
      </BasePopover.Root>
    </div>
  );
}

import type { KeyboardEvent } from "react";
import * as z from "zod/mini";

// Some browsers clear isComposing before dispatching the confirmation key.
const compositionConfirmation = z.object({ keyCode: z.literal(229) });

/** Native composition, including confirmation events whose flag is already false. */
export function isImeComposing(
  event: Pick<KeyboardEvent, "nativeEvent">,
): boolean {
  return (
    event.nativeEvent.isComposing ||
    z.safeParse(compositionConfirmation, event.nativeEvent).success
  );
}

import { useCallback, useRef, type RefCallback } from "react";

import { canAnimate, motionEasing, readMotion } from "./motion.js";

type Box = Readonly<{ x: number; y: number; width: number; height: number }>;

/**
 * The attribute a row carries while the glide stands in for its highlight:
 * empty while the stand-in travels, `measure` while its resting colour is read.
 */
const glideStandInAttribute = "data-glide-stand-in";

function boxIn(host: HTMLElement, element: Element): Box {
  const outer = host.getBoundingClientRect();
  const inner = element.getBoundingClientRect();
  // Host-relative and scroll-aware, so a scrolled list glides true.
  return {
    x: inner.left - outer.left + host.scrollLeft - host.clientLeft,
    y: inner.top - outer.top + host.scrollTop - host.clientTop,
    width: inner.width,
    height: inner.height,
  };
}

function place(box: Box) {
  return {
    transform: `translate(${String(box.x)}px, ${String(box.y)}px)`,
    width: `${String(box.width)}px`,
    height: `${String(box.height)}px`,
  };
}

/**
 * One highlight that glides between a list's rows instead of blinking from
 * row to row. `lit` selects the highlighted row (keyboard or pointer). While
 * the highlight moves, a single stand-in carrying that row's own resting
 * background and radius travels from the previous row and the rows' own
 * highlights are held back, so at rest every row looks exactly as it always
 * has. Within one open list the glide remembers its last row, so leaving and
 * re-entering glides from where it was. Timing and easing are the theme's;
 * reduced motion moves the highlight at once.
 */
export function useGlide(lit: string): RefCallback<HTMLElement> {
  const detach = useRef<(() => void) | null>(null);
  // A callback ref, so a list that mounts later (a popover's) still glides.
  return useCallback(
    (element: HTMLElement | null) => {
      detach.current?.();
      detach.current = element ? attachGlide(element, lit) : null;
    },
    [lit],
  );
}

function attachGlide(element: HTMLElement, lit: string): () => void {
  if (!canAnimate(element)) return () => undefined;
  const document = element.ownerDocument;
  let current: Element | null = element.querySelector(lit);
  let last: Box | null = current ? boxIn(element, current) : null;
  let ghost: HTMLSpanElement | null = null;
  let flight: Animation | null = null;
  const standIns = new Set<Element>();

  const release = () => {
    for (const row of standIns) row.removeAttribute(glideStandInAttribute);
    standIns.clear();
    if (ghost) ghost.hidden = true;
    flight = null;
  };

  const stage = () => {
    if (ghost) return ghost;
    const created = document.createElement("span");
    created.className = "caps-glide";
    created.setAttribute("aria-hidden", "true");
    element.prepend(created);
    // The stand-in paints above the list's background, below its rows.
    element.classList.add("caps-glide-host");
    if (getComputedStyle(element).position === "static")
      element.classList.add("caps-glide-anchor");
    ghost = created;
    return created;
  };

  const glide = (to: Element, away: Element | null) => {
    const motion = readMotion(element);
    const target = boxIn(element, to);
    const from = flight && ghost ? boxIn(element, ghost) : last;
    last = target;
    flight?.cancel();
    release();
    if (motion.reduced || from === null) return;
    if (Math.abs(from.y - target.y) < 1 && Math.abs(from.x - target.x) < 1)
      return;
    // Read the row's resting highlight, not a frame of its colour transition.
    to.setAttribute(glideStandInAttribute, "measure");
    const style = getComputedStyle(to);
    const background = style.backgroundColor;
    const radius = style.borderRadius;
    for (const row of [to, away]) {
      if (!row) continue;
      row.setAttribute(glideStandInAttribute, "");
      standIns.add(row);
    }
    const stand = stage();
    stand.hidden = false;
    stand.style.backgroundColor = background;
    stand.style.borderRadius = radius;
    const animation = stand.animate([place(from), place(target)], {
      duration: motion.normal,
      easing: motionEasing(motion, motion.ease),
      fill: "forwards",
    });
    flight = animation;
    animation.addEventListener("finish", () => {
      if (flight === animation) release();
    });
  };

  const update = () => {
    const next = element.querySelector(lit);
    if (next === current) return;
    const away = current;
    current = next;
    // A row that lights from nothing glides from the remembered row.
    if (next) glide(next, away);
  };

  const observer = new MutationObserver(update);
  observer.observe(element, {
    subtree: true,
    attributes: true,
    attributeFilter: [
      "data-highlighted",
      "data-active",
      "data-navigation",
      "aria-selected",
    ],
  });
  element.addEventListener("pointerover", update);
  element.addEventListener("pointerout", update);
  return () => {
    observer.disconnect();
    element.removeEventListener("pointerover", update);
    element.removeEventListener("pointerout", update);
    flight?.cancel();
    release();
    ghost?.remove();
  };
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  type ReactNode,
} from "react";

/** Semantic destinations; the host owns their paint order and positioning. */
export type OverlayLayer = "popover" | "dialog" | "toast" | "tooltip";
/** Host portal roots; null keeps an overlay waiting until its layer mounts. */
export type OverlayContainers = Readonly<
  Record<OverlayLayer, HTMLElement | null>
>;

const DismissContext = createContext<
  ((listener: () => void) => () => void) | undefined
>(undefined);

const Context = createContext<OverlayContainers | null>(null);

/** Supply shell portal roots without teaching Caps about the shell's layout. */
export function OverlayRoot({
  containers,
  children,
  subscribeDismiss,
}: {
  containers: OverlayContainers;
  children?: ReactNode;
  /** Subscribe to the host losing focus to a child surface or another window. */
  subscribeDismiss?: (listener: () => void) => () => void;
}) {
  return (
    <Context.Provider value={containers}>
      <DismissContext.Provider value={subscribeDismiss}>
        {children}
      </DismissContext.Provider>
    </Context.Provider>
  );
}

/** Wait for a provided root; standalone overlays use the current document body. */
export function useOverlayRoot(layer: OverlayLayer): HTMLElement | null {
  const containers = useContext(Context);
  if (containers !== null) return containers[layer];
  return Object.hasOwn(globalThis, "document") ? document.body : null;
}

/** Retire a transient overlay when its owning host requests light dismissal. */
export function useOverlayDismiss(dismiss: () => void): void {
  const subscribe = useContext(DismissContext);
  const callback = useRef(dismiss);
  callback.current = dismiss;
  useEffect(
    () =>
      subscribe?.(() => {
        callback.current();
      }),
    [subscribe],
  );
}

